import type { Question, TopicId } from "./types";

function q(
  id: string,
  topic: TopicId,
  prompt: string,
  options: [string, string, string, string],
  answer: 0 | 1 | 2 | 3,
  explain: string,
  article: string,
  extra?: Partial<Pick<Question, "hot" | "scene" | "sign">>,
): Question {
  return { id, topic, prompt, options, answer, explain, article, hot: extra?.hot, scene: extra?.scene, sign: extra?.sign };
}

